                wait_sys_clk_cycles(1);

                write_enable <= '0';
                read_enable <= '1';
                read_address <= to_unsigned(i, read_address'length);
                wait_sys_clk_cycles(1);
                check_equal(got => data_out, expected => data_in, msg => "data_out");
